"""costC1C2Flag optimized emitter (920B SVE1+NEON).

The C reference runs one CABAC state transition per coefficient. For the
common C1FLAG_NUMBER==8 chunk, the c1 context sequence collapses into at
most four runs (ctx1, ctx3-before-first-1, ctx3-at-first-1, ctx0-after).
We cache (state, symbol, run-length) -> next-state/entropy-bits so each run
is one table lookup instead of a per-coefficient loop.
"""


def emit(func_name="dynopt_cost_c1c2_flag_sve2"):
    return r"""\
// Generated by tools/emit_cost_c1c2_flag_sve2_shared.py -- do not edit.
#include <arm_neon.h>
#include <stdint.h>
#include <stddef.h>

#include "common/cpu.h"
#include "common/contexts.h"

using namespace X265_NS;

static uint8_t  dynopt_c1_next[128][2][9];
static uint32_t dynopt_c1_bits[128][2][9];
static bool     dynopt_c1_ready = false;

static void dynopt_c1_init()
{
    for (int s = 0; s < 128; s++)
    {
        for (int sym = 0; sym < 2; sym++)
        {
            uint8_t st = (uint8_t)s;
            uint32_t bits = 0;
            dynopt_c1_next[s][sym][0] = st;
            dynopt_c1_bits[s][sym][0] = 0;
            for (int n = 1; n <= 8; n++)
            {
                bits += g_entropyBits[st ^ sym];
                st = g_nextState[st][sym];
                dynopt_c1_next[s][sym][n] = st;
                dynopt_c1_bits[s][sym][n] = bits;
            }
        }
    }
    dynopt_c1_ready = true;
}

static inline void dynopt_c1_run(uint8_t& st, int sym, int len,
                                 uint32_t& sum)
{
    if (len <= 0)
        return;
    sum += dynopt_c1_bits[st][sym][len];
    st = dynopt_c1_next[st][sym][len];
}

extern "C" uint32_t dynopt_cost_c1c2_flag_sve2(
    uint16_t* absCoeff, intptr_t numC1Flag, uint8_t* baseCtxMod,
    intptr_t ctxOffset)
{
    if (!dynopt_c1_ready)
        dynopt_c1_init();

    const int n = (int)numC1Flag;
    if (n <= 0)
        return (0 << 26) + (8 << 28);
    if (n > 8)
    {
        // Rare large chunk: scalar reference path.
        uint32_t sum = 0;
        uint32_t c1 = 1, firstC2Idx = 8, firstC2Flag = 2, c1Next = 0xFFFFFFFE;
        for (int idx = 0; idx < n; idx++)
        {
            const uint32_t symbol1 = absCoeff[idx] > 1;
            const uint32_t symbol2 = absCoeff[idx] > 2;
            const uint32_t mstate = baseCtxMod[c1];
            baseCtxMod[c1] = sbacNext(mstate, symbol1);
            sum += sbacGetEntropyBits(mstate, symbol1);
            if (symbol1)
                c1Next = 0;
            if (symbol1 + firstC2Flag == 3)
                firstC2Flag = symbol2;
            if (symbol1 + firstC2Idx == 9)
                firstC2Idx = (uint32_t)idx;
            c1 = c1Next & 3;
            c1Next >>= 2;
        }
        if (!c1)
        {
            uint8_t* ctx = baseCtxMod + ctxOffset;
            const uint32_t mstate = ctx[0];
            ctx[0] = sbacNext(mstate, firstC2Flag);
            sum += sbacGetEntropyBits(mstate, firstC2Flag);
        }
        return (sum & 0x00FFFFFF) + (c1 << 26) + (firstC2Idx << 28);
    }

    // NEON masks for symbol1/symbol2.
    uint16x8_t a = vld1q_u16(absCoeff);
    uint16x8_t one = vdupq_n_u16(1), two = vdupq_n_u16(2);
    uint16x8_t s1 = vcgtq_u16(a, one);
    uint16x8_t s2 = vcgtq_u16(a, two);
    uint16_t s1a[8], s2a[8];
    vst1q_u16(s1a, s1);
    vst1q_u16(s2a, s2);
    uint16_t m1 = 0, m2 = 0;
    for (int i = 0; i < 8; i++)
    {
        m1 |= (uint16_t)((s1a[i] ? 1 : 0) << i);
        m2 |= (uint16_t)((s2a[i] ? 1 : 0) << i);
    }
    const int first = m1 ? __builtin_ctz((unsigned)m1) : n;
    const uint32_t firstSym2 = (first < n && (m2 >> first) & 1) ? 1 : 0;

    uint32_t sum = 0;
    uint8_t st;

    // idx 0 uses ctx 1.
    st = baseCtxMod[1];
    dynopt_c1_run(st, (m1 >> 0) & 1, 1, sum);
    baseCtxMod[1] = st;

    // idx 1 uses ctx 2.
    if (n > 1 && first > 1)
    {
        st = baseCtxMod[2];
        dynopt_c1_run(st, (m1 >> 1) & 1, 1, sum);
        baseCtxMod[2] = st;
    }

    // ctx 3 run before the first symbol1 (indices 2..first-1), all symbol0.
    if (first > 2)
    {
        st = baseCtxMod[3];
        dynopt_c1_run(st, 0, first - 2, sum);
        baseCtxMod[3] = st;
    }

    // first symbol1 itself: ctx 3 for first >= 2, ctx 2 for first == 1,
    // ctx 1 for first == 0 (already handled above).
    if (first >= 2 && first < n)
    {
        st = baseCtxMod[3];
        dynopt_c1_run(st, 1, 1, sum);
        baseCtxMod[3] = st;
    }
    else if (first == 1 && first < n)
    {
        st = baseCtxMod[2];
        dynopt_c1_run(st, 1, 1, sum);
        baseCtxMod[2] = st;
    }

    // ctx 0 tail after the first symbol1. Symbols can still be 1, so group
    // consecutive equal bits and apply the run cache per group.
    int tail = first == 0 ? 1 : first + 1;
    if (tail < n)
    {
        st = baseCtxMod[0];
        while (tail < n)
        {
            const int sym = (m1 >> tail) & 1;
            int end = tail + 1;
            while (end < n && ((m1 >> end) & 1) == sym)
                end++;
            dynopt_c1_run(st, sym, end - tail, sum);
            tail = end;
        }
        baseCtxMod[0] = st;
    }

    const uint32_t c1 = (first < n) ? 0 : (n == 1 ? 2 : 3);
    const uint32_t firstC2Idx = (first < n) ? (uint32_t)first : 8;
    const uint32_t firstC2Flag = (first < n) ? firstSym2 : 2;
    if (!c1)
    {
        uint8_t* ctx = baseCtxMod + ctxOffset;
        st = ctx[0];
        dynopt_c1_run(st, (int)firstC2Flag, 1, sum);
        ctx[0] = st;
    }
    return (sum & 0x00FFFFFF) + (c1 << 26) + (firstC2Idx << 28);
}
""".replace("dynopt_cost_c1c2_flag_sve2", func_name)


def emit_combo(combo):
    return emit()
